global.nav=async(id,side=true,page=p)=>{await page.locator(side?'[data-srm-v2-tab="'+id+'"]':(id==='settings'?'#uiFieldSettings':'.ui-workNav [data-tab="'+id+'"]').click();await check('navigation '+id,{side:await page.locator('.srm-v2-sideitem[aria-current="page"]').getAttribute('data-srm-v2-tab'),tab:await page.locator('.tab.active').first().getAttribute('data-tab'),panel:await page.locator('section.panel.active').getAttribute('id')},{side:id,tab:id,panel:id})};
for(const id of ['#uiProjectDetails','#uiSupplierTools','#uiDataTools','#uiDrawingTools'])if(await p.locator(id).evaluate(e=>e.open))await p.locator(id+' > summary').click();
global.geometry=[];
for(const [width,height]of [[1024,768],[1366,768],[1600,900]]){await p.setViewportSize({width,height});for(const id of ['items','assign','quoteImport','quotes','settings']){await nav(id);if(id==='assign')await p.locator('.modebtn[data-mode="itemFirst"]').click();await p.evaluate(()=>window.scrollTo(0,0));await p.waitForTimeout(500);const g=await p.evaluate(()=>{const rect=s=>{const e=document.querySelector(s);if(!e)return null;let r=e.getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom}};return{viewport:{width:innerWidth,height:innerHeight},documentWidth:document.documentElement.scrollWidth,sidebar:rect('.srm-v2-sidebar'),panel:rect('section.panel.active'),firstMaterial:rect('#itemBody tr'),firstAssign:rect('#assignItemBody tr'),font:getComputedStyle(document.body).font,visibleButtons:[...document.querySelectorAll('section.panel.active button')].filter(e=>e.getClientRects().length).map(e=>{let r=e.getBoundingClientRect();return{id:e.id,text:e.innerText,left:r.left,right:r.right,top:r.top,bottom:r.bottom}})}});geometry.push({page:id,...g});await check(width+' '+id+' document no horizontal overflow',g.documentWidth<=width,true);await check(width+' '+id+' panel clear of sidebar',g.panel.x>=g.sidebar.right,true);await shot('viewport-'+width+'-'+id);if(id==='assign'){await tell(width+' allocation first row',g.firstAssign);await p.locator('#assignItemBody tr').first().scrollIntoViewIfNeeded();await shot('table-'+width+'-allocation')}if(id==='quoteImport'){await p.locator('#quoteRoundBody').scrollIntoViewIfNeeded();await p.locator('#quoteRoundBody').hover();await p.mouse.wheel(1800,0);await p.waitForTimeout(300);await shot('table-'+width+'-quote-right');await tell(width+' quote scroll',await p.locator('#quoteRoundBody').evaluate(e=>{let w=e.closest('.tablewrap');return{scrollLeft:w.scrollLeft,scrollWidth:w.scrollWidth,clientWidth:w.clientWidth}}))}}}
fs.writeFileSync(root+'responsive-geometry.json',JSON.stringify(geometry,null,2));await p.setViewportSize({width:1024,height:768});await nav('items',false);await p.locator('[data-srm-v2-tab="items"]').focus();await p.keyboard.press('Tab');await tell('keyboard focus',await p.evaluate(()=>{let e=document.activeElement,s=getComputedStyle(e);return{tag:e.tagName,ariaLabel:e.getAttribute('aria-label'),outline:s.outline,focusVisible:e.matches(':focus-visible')}}));await shot('keyboard-focus-1024');await p.keyboard.press('Enter');await check('keyboard sidebar activates allocation',await p.locator('section.panel.active').getAttribute('id'),'assign');await nav('quotes',false);await check('responsive navigation keeps business data',fp('06-responsive-state'),awarded);

